import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
answers = []


def add(number, xml, reason, notes, removed=None, benefit=None, repeal=None):
    source = next(a for a in sources if a['number'] == number)
    result = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    result.update(proposed_xml=xml.strip(), reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        result.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        result.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if benefit:
        result['benefit_review'] = benefit
    answers.append(result)


add('L6222-18-2', '''
<p>Lorsque le contrat d'apprentissage est rompu dans les conditions de l'article L. 6222-18, le centre de formation dans lequel l'apprenti est inscrit lui permet de poursuivre sa formation théorique pendant six mois. Il l'aide à trouver un nouvel employeur auprès duquel il pourra achever son cycle de formation.</p>
<p>Pendant cette période, l'apprenti bénéficie du statut de stagiaire de la formation professionnelle.</p>
<p>Ces garanties s'appliquent également à la rupture d'un contrat unique à durée indéterminée pendant sa période d'apprentissage. La seule fin de cette période de formation ne rompt pas le contrat de travail.</p>
''',
"Droit constant pour les six mois de poursuite de la formation, l'aide à la recherche d'un employeur et le statut de stagiaire. Coordination de fond : ces protections sont expressément ouvertes aux ruptures des nouveaux contrats uniques pendant l'apprentissage. Aucune formalité autonome inutile n'est imposée par cet article ; supprimer l'obligation du centre retirerait une garantie de continuité de formation.",
"L. 6222-18 a été lu dans le corpus, source et proposition : son nouveau régime de rupture renvoie au contrat unique et conserve le régime des anciens contrats. Le présent article ne crée ni fin automatique de l'emploi après six mois, ni nouvelle période d'essai chez le même employeur. Maintenir la coordination du financement et du statut avec L. 6332-14 II et L. 6341-1 ; le droit de poursuivre la formation n'est pas assimilé à un salaire dû par l'ancien employeur.")

add('L6222-21', '''
<p>Pour les contrats uniques à durée indéterminée conclus à compter de l'entrée en vigueur de la loi instituant ce contrat, la rupture relève des règles d'indemnisation de ce contrat. L'indemnité ordinaire n'est due que lorsque l'employeur rompt le contrat et que le salarié atteint un an d'ancienneté à la date de sa fin effective, préavis inclus. Elle est alors égale à 0,20 mois de salaire par année d'ancienneté totale, les fractions d'année étant prises en compte au prorata, dans la limite de six mois de salaire. La première année est comprise dans ce calcul. Aucune indemnité ordinaire n'est due avant ce seuil ni en cas de démission ordinaire.</p>
<p>Cette règle ne fait obstacle ni à une stipulation contractuelle plus favorable, ni au paiement des salaires, des congés payés acquis et de l'indemnité compensatrice de préavis lorsqu'elle est due, ni aux réparations d'une rupture illégale ou discriminatoire, ni aux garanties de maternité et aux indemnités spéciales, notamment pour inaptitude professionnelle.</p>
<p>Pour les contrats d'apprentissage conclus avant cette entrée en vigueur et à compter du 1er janvier 2019, la rupture pendant les quarante-cinq premiers jours, consécutifs ou non, de formation pratique en entreprise visés au premier alinéa de l'article L. 6222-18 dans sa rédaction antérieure ne donne pas lieu à une indemnité de rupture, sauf stipulation contractuelle contraire. Cette disposition ne supprime pas les créances de salaire ou de congés, ni la réparation d'une illégalité. Les contrats conclus avant le 1er janvier 2019 restent soumis aux règles qui leur étaient applicables.</p>
''',
"Réforme de fond : l'exclusion d'indemnité attachée aux quarante-cinq jours de pratique n'est pas étendue au nouvel essai ou au nouveau contrat unique. Le régime ordinaire décidé par l'auteur est rendu explicite, avec les droits distincts et les stipulations plus favorables. Le dispositif source est réécrit pour le seul stock ancien et conserve sa limite historique du 1er janvier 2019.",
"Coordonner L. 6222-18, L. 1234-9 et R. 1234-1, R. 1234-2 et R. 1234-4 : quinze jours calendaires de préavis individuel selon le nouveau régime ; ancienneté appréciée à la fin effective avec ce préavis ; toute l'ancienneté entre dans le calcul dès un an. L. 1226-14, L. 1226-16 et L. 1226-20 gardent leurs règles spéciales, dont le doublement et l'absence de seuil. La note de l'article 46 II de la loi de 2018 est conservée dans le champ transitoire, sans en faire une date future de réforme. La conversion éventuelle d'un ancien contrat conserve ancienneté et créances, sans double compte d'une même période.")

add('L6222-37', '''
<p>Pour les personnes handicapées, les dispositions suivantes font l'objet d'aménagements :</p>
<p>1° Les articles L. 6222-1 à L. 6222-3, qui fixent les conditions de conclusion du contrat d'apprentissage ;</p>
<p>2° Les articles L. 6222-7 à L. 6222-10, relatifs à la durée de l'apprentissage ; pour les contrats uniques à durée indéterminée, les aménagements portent sur la période d'apprentissage et non sur la durée de l'emploi ;</p>
<p>3° L'article L. 6222-15, relatif à la succession des apprentissages ;</p>
<p>4° L'article L. 6222-19, qui permet à l'apprenti de mettre fin au contrat à son initiative après l'obtention du diplôme ou du titre préparé ;</p>
<p>5° Les articles L. 6223-3 et L. 6223-4, relatifs aux obligations de formation de l'employeur ;</p>
<p>6° Le second alinéa de l'article L. 6222-24, relatif au temps de travail dans l'entreprise.</p>
<p>Ces aménagements restent ouverts aux personnes éligibles recrutées sous contrat unique. Ils ne permettent ni de conclure un nouveau contrat à durée déterminée, ni de mettre automatiquement fin à l'emploi à l'issue d'une formation. Les contrats antérieurs à l'entrée en vigueur de la loi instituant le contrat unique conservent les aménagements et les droits qui leur sont applicables.</p>
''',
"Réécriture des six renvois, sans retrait des aménagements favorables liés au handicap. Réforme de fond limitée à la coordination : la durée aménageable devient celle de la phase pédagogique pour les nouvelles embauches et ne constitue plus une autorisation de contrat à terme. La faculté de départ après obtention du diplôme reste distincte d'une cessation automatique de l'emploi.",
"Les subdivisions 1° à 6° sont conservées. L. 6222-1 à L. 6222-3, L. 6222-7, L. 6222-7-1, L. 6222-15, L. 6222-19, L. 6222-24 et L. 6223-3 à L. 6223-4 ont été lus. Le corpus ne fournit pas de fiche pour L. 6222-8 à L. 6222-10 : les renvois sources sont conservés, sans supposer le rétablissement d'articles absents. L. 6222-19, hors lot, reste à coordonner avec la dispense favorable de préavis liée au diplôme ; ne pas transformer son droit de départ en terme imposé. Les règlements d'aménagement du handicap doivent conserver leurs avantages sans rétablir de CDD.")

add('L6222-40', '''
<p>Les sportifs de haut niveau bénéficient d'aménagements aux dispositions suivantes :</p>
<p>1° Les articles L. 6222-7 à L. 6222-10, relatifs à la durée de l'apprentissage ; pour les contrats uniques à durée indéterminée, ces aménagements portent sur la période d'apprentissage ;</p>
<p>2° Le second alinéa de l'article L. 6222-24, relatif au temps de travail dans l'entreprise.</p>
<p>Pour les contrats conclus à compter de l'entrée en vigueur de la loi instituant le contrat unique, la durée ainsi aménagée ne limite pas celle de l'emploi et son expiration ne rompt pas le contrat. Les aménagements demeurent ouverts aux futurs sportifs éligibles. Les contrats conclus auparavant conservent les règles et les droits qui leur étaient applicables.</p>
''',
"Droit constant pour les deux catégories d'aménagements favorables aux sportifs de haut niveau. Coordination de fond avec le contrat unique : la souplesse pédagogique et l'aménagement du travail sont conservés, mais ne fondent plus un contrat à terme ni une fin automatique d'emploi.",
"Conserver 1° et 2° et le renvoi exact au second alinéa de L. 6222-24. L. 6222-7 et L. 6222-7-1 ont été lus ; les fiches L. 6222-8 à L. 6222-10 sont absentes du corpus fourni. Les dispositions réglementaires propres aux sportifs doivent être raccordées à la période de formation, sans fermer les prolongations favorables ou recréer un essai à chaque phase sportive.")

add('L6222-43', '''
<p>Les apprentis originaires d'un État membre de l'Union européenne qui effectuent une période de mobilité en France bénéficient des dispositions du présent livre. Compte tenu du caractère temporaire de leur mobilité, les dispositions suivantes ne leur sont pas applicables :</p>
<p>1° L'article L. 6211-1, relatif à la finalité du contrat d'apprentissage ;</p>
<p>2° L'article L. 6222-7-1, relatif à la durée de l'apprentissage ;</p>
<p>3° Le deuxième alinéa de l'article L. 6222-12, relatif aux conditions d'intégration d'une formation en apprentissage ;</p>
<p>4° L'article L. 6211-2, relatif à la durée de la formation en apprentissage ;</p>
<p>5° Le premier alinéa de l'article L. 6222-1, relatif à l'âge requis pour débuter un apprentissage.</p>
<p>Ces dispenses demeurent applicables aux mobilités futures. La durée du séjour ou de la formation en France ne constitue pas, à elle seule, un terme du contrat de travail. Le présent article n'impose pas de conclure un nouveau contrat français pour une mobilité exécutée dans le cadre d'un contrat étranger ; lorsqu'une nouvelle relation de travail relevant du droit privé français est conclue après l'entrée en vigueur de la loi instituant le contrat unique, elle relève de ce contrat à durée indéterminée.</p>
''',
"Les cinq dispenses favorables de mobilité européenne sont maintenues et reformulées. Coordination de fond : le séjour temporaire demeure possible, sans devenir un cas de nouveau CDD français. Le texte distingue la mobilité sous contrat étranger d'une nouvelle embauche de droit privé français ; il ne prétend pas convertir un contrat étranger.",
"Les cinq textes visés ont été lus. Le deuxième alinéa de L. 6222-12 pose actuellement la limite de trois mois pour le début de formation pratique : le libellé source plus général est conservé, sans étendre la dispense au troisième alinéa relatif au centre. Le 5° conserve tout le premier alinéa de L. 6222-1, comprenant les bornes d'âge, sans réduire l'exemption à une seule borne. Les règles européennes de conflit de lois, de détachement et de protection sociale restent distinctes ; aucun effet extraterritorial du contrat unique n'est affirmé.")

add('L6227-2', '''
<p>Le présent article est abrogé à compter de l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. L'obligation de conclure pour une durée limitée un contrat d'apprentissage dans le secteur public non industriel et commercial cesse pour les nouveaux contrats d'apprentissage de droit privé régis par le présent livre. Ces contrats relèvent de l'article L. 6222-7 ; seule leur période d'apprentissage peut être limitée, sans cessation automatique de l'emploi.</p>
<p>Les contrats conclus avant cette entrée en vigueur restent régis par les règles qui leur étaient applicables jusqu'à leur terme, sans nouveau contrat à durée déterminée ni renouvellement à terme après cette date. Leurs rémunérations, exonérations, prises en charge, garanties sociales, créances et recours sont conservés. Une conversion convenue en contrat unique conserve toute l'ancienneté et les créances acquises.</p>
<p>La suppression de l'obligation de durée limitée ne modifie ni les statuts des fonctionnaires et agents publics, ni les conditions d'accès à un emploi public, et n'emporte aucune titularisation. Les apprentissages futurs éligibles conservent les exonérations, prises en charge de formation et garanties sociales de ce chapitre pendant leur période d'apprentissage.</p>
''',
"Abrogation de fond de la dérogation qui imposait un terme aux apprentissages du secteur public non industriel et commercial. Elle est incompatible avec les nouveaux emplois de droit privé à durée indéterminée. Les contrats anciens sont protégés et les avantages de l'apprentissage public restent ouverts aux futurs apprentis, sans réforme implicite du statut des agents publics.",
"L. 6227-1, L. 6227-3 à L. 6227-6, L. 6227-8 à L. 6227-12 et D. 6275-1 et D. 6275-2 ont été lus. Coordonner le chapitre public et ses règlements avec L. 6222-7 et L. 6222-18 ; ni la convention de financement ni le dépôt n'imposent un terme à l'emploi. Le contrat d'apprentissage de droit privé demeure distinct du recrutement statutaire public. La présente abrogation ne généralise pas les exonérations de la seule période d'apprentissage à toute la carrière ultérieure.",
benefit="La durée limitée est ici une obligation générale de forme, et non une exonération fiscale ou une aide attribuée à l'apprenti. Sa suppression ne ferme aucun apprentissage futur. Sont expressément conservés, dans leur champ et pendant la phase d'apprentissage, la prise en charge des coûts de formation de L. 6227-6, l'affiliation et les validations vieillesse de L. 6227-8, l'exonération patronale de L. 6227-8-1 avec sa réserve AT-MP, ainsi que la faculté d'adhésion chômage et les prises en charge de L. 6227-9. Aucun statut de fonctionnaire ni droit à titularisation n'est créé ou retiré.",
repeal="Obligation de conclure les nouveaux contrats d'apprentissage du secteur public non industriel et commercial pour une durée limitée, par dérogation au régime à durée indéterminée de L. 6222-7.")

add('L6227-12', '''
<p>Les dispositions relatives à l'apprentissage s'appliquent au secteur public non industriel et commercial, à l'exception des articles L. 6222-5, L. 6222-13, L. 6222-16, L. 6222-31, L. 6222-39, L. 6224-1, L. 6225-1 à L. 6225-3-1, L. 6243-1 et L. 6243-1-2.</p>
<p>Un règlement détermine les modalités de mise en œuvre du présent chapitre.</p>
<p>Pour les nouveaux contrats d'apprentissage de droit privé conclus à compter de l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, ces modalités ne peuvent imposer de terme à l'emploi ni de nouvel essai du seul fait de l'achèvement ou du renouvellement d'une phase de formation. Les exceptions du premier alinéa ne retirent ni l'ancienneté ni les créances acquises au titre du même contrat. Les contrats antérieurs et les statuts des agents publics conservent leur régime propre.</p>
''',
"Réécriture de la règle d'application et de ses exceptions, sans importer les aides privées expressément exclues du secteur public. Coordination de fond avec la suppression de L. 6227-2 : l'habilitation réglementaire ne peut rétablir le terme de l'emploi ou un nouvel essai à chaque phase pédagogique.",
"La liste des références du premier alinéa est conservée dans son ordre, y compris l'exclusion de L. 6222-16. Cette exclusion ne doit pas être interprétée comme autorisant un second essai au sein du même nouveau contrat unique ou la remise à zéro de son ancienneté. Maintenir les mécanismes publics distincts de médiation, dépôt, contrôle et aides. D. 6275-1 et D. 6275-2 lus : le contrôle des conditions d'âge, de rémunération, de formation et de certification n'est pas supprimé ici. Ne pas considérer les autres règlements publics comme réécrits par cette seule clause.")

add('L6242-1', '''
<p>I.-La contribution supplémentaire à l'apprentissage est supprimée pour les années civiles commençant le 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi portant cette suppression. Aucun prélèvement de remplacement ni complément de taxe d'apprentissage n'est dû sur son seul fondement.</p>
<p>Pour l'application de la créance prévue au II de l'article L. 6241-2, la référence aux entreprises redevables de cette contribution désigne les entreprises d'au moins deux cent cinquante salariés redevables de la taxe d'apprentissage en application de l'article L. 6241-1. Le quotient de l'effectif salarié annuel des catégories mentionnées au II du présent article par l'effectif salarié annuel total de l'entreprise reste calculé pour apprécier le dépassement du seuil de 5 % ouvrant droit à cette créance. La suppression de la contribution ne supprime ni cette créance ni ses conditions de calcul et d'imputation sur le solde de taxe d'apprentissage.</p>
<p>II.-Sont pris en compte au numérateur de ce quotient :</p>
<p>1° Les salariés sous contrat de professionnalisation ou d'apprentissage ; dans un contrat unique, cette qualité est retenue pendant l'action de professionnalisation ou la période d'apprentissage. Pour les contrats antérieurs à la loi instituant le contrat unique, sont également pris en compte, pendant l'année suivant la fin du contrat de professionnalisation ou d'apprentissage, les salariés embauchés à durée indéterminée par la même entreprise à l'issue de ce contrat. Pour les contrats uniques, sont également pris en compte, pendant l'année suivant la fin de la période d'apprentissage ou de l'action de professionnalisation, les salariés dont l'emploi se poursuit dans cette entreprise ; la poursuite du même contrat ne nécessite aucune nouvelle embauche et un salarié n'est compté qu'une fois pour une même période ;</p>
<p>2° Les bénéficiaires d'une convention industrielle de formation par la recherche.</p>
<p>III.-L'assiette de la contribution supplémentaire à l'apprentissage est supprimée pour les années visées au premier alinéa du I.</p>
<p>IV.-Les taux de cette contribution sont supprimés pour ces mêmes années.</p>
<p>V.-Pour le quotient et l'effectif mentionnés au I, l'effectif salarié est apprécié selon le I de l'article L. 130-1 du code de la sécurité sociale, en retenant l'année au titre de laquelle la créance est calculée. Les règles du II du même article relatives au franchissement du seuil de deux cent cinquante salariés restent applicables sans pouvoir priver une entreprise de la créance du seul fait qu'elle est dispensée de contribution supplémentaire.</p>
<p>Pour les entreprises de travail temporaire mentionnées à l'article L. 1251-2, l'exclusion des titulaires de contrats de mission mentionnés au 2° de l'article L. 1251-1 pour apprécier le seuil de deux cent cinquante salariés reste applicable aux anciens contrats. Elle n'est pas étendue aux salariés titulaires du nouveau contrat unique à durée indéterminée : leur prise en compte ne rétablit aucune contribution et ne ferme pas l'accès à la créance.</p>
<p>Les salariés en contrat de professionnalisation ou d'apprentissage mis à disposition par un groupement d'employeurs pour l'insertion et la qualification mentionné au troisième alinéa de l'article L. 1253-1 sont pris en compte par l'entreprise utilisatrice dans le quotient du I. Cette règle s'applique aussi aux périodes d'apprentissage et aux actions de professionnalisation des contrats uniques.</p>
<p>VI.-La réduction territoriale des taux de contribution n'a plus d'objet pour les années où cette contribution est supprimée ; elle reste applicable aux années antérieures dans les conditions du VIII.</p>
<p>VII.-Les arrondis de la créance imputable sur le solde de taxe d'apprentissage restent régis par le III de l'article L. 6241-2. Aucun calcul ni aucune déclaration d'assiette de contribution supplémentaire n'est exigé pour les années où celle-ci est supprimée.</p>
<p>VIII.-Pour les années antérieures à celles mentionnées au premier alinéa du I, la contribution, ses seuils, son assiette, ses taux, ses exonérations, ses exclusions, sa réduction territoriale, ses arrondis, son échéance, son recouvrement, ses restitutions, ses prescriptions et ses recours restent régis par les dispositions applicables à ces années, y compris lorsque le paiement ou le remboursement intervient ultérieurement. La suppression ne crée aucun remboursement général des contributions légalement dues pour ces années.</p>
<p>Pour les années nouvelles, aucune déclaration, aucun versement de mars ni aucune transmission de liste exclusivement justifiés par la contribution supprimée ne sont exigés. Les calculs nécessaires à la créance de l'article L. 6241-2 utilisent les données légalement disponibles, sans déclaration de contribution supplémentaire. L'aide au recrutement prévue à l'article L. 6243-1-2 reste accessible aux entreprises définies au deuxième alinéa du I, sans transmission annuelle d'une liste de redevables de la contribution supprimée.</p>
''',
"Réduction de fond : suppression totale de la contribution supplémentaire, de ses taux et de son circuit annuel pour les années nouvelles, sans taxe de remplacement. L'article n'est pas classé comme abrogé en entier : ses définitions utiles sont autonomisées pour préserver la créance favorable sur le solde de taxe d'apprentissage et l'accès à l'aide au recrutement. La période de formation du nouveau contrat unique est prise en compte sans imposer une nouvelle embauche à sa fin. Les années anciennes conservent intégralement leur régime.",
"L. 6131-1, L. 6241-2 et L. 6243-1-2 ont été lus. Coordination à répercuter au 3° du I de L. 6131-1, au II de L. 6241-2 et à L. 6243-1-2 ; ces articles hors lot ne sont pas modifiés ici. La source L. 6241-2 vise paradoxalement des entreprises redevables de CSA dépassant le seuil qui les en dispense : la catégorie de bénéficiaires est explicitée ici, sans fermer la créance. Restent à L. 6241-2 la limite de deux points, le multiplicateur compris entre 2,50 € et 5,00 €, l'effectif annuel moyen au 31 décembre, l'imputation sur le solde et l'absence de report ou restitution. Ancien droit conservé : 250/2 000 salariés ; 5 %, 3 % et progression de 10 % ; taux 0,4/0,6/0,2/0,1/0,05 % ; réduction à 52 % pour les établissements du deuxième alinéa du II de L. 6241-1-1 (la source omet le préfixe L. dans ce renvoi). L'exclusion des rémunérations des salariés de mission demeure pour les anciennes années. La transition au prochain 1er janvier respecte l'annualité : aucune ventilation ou recette de compensation inventée. Les besoins de financement de l'apprentissage restent à documenter, sans rendement supposé de la réforme de l'IS.",
removed=["Contribution supplémentaire annuelle à l'apprentissage, avec son assiette de rémunérations et l'intégralité de ses taux, pour les années civiles nouvelles définies au I.", "Versement unique de mars, déclaration d'assiette et transmission annuelle de liste exclusivement attachés à la contribution supplémentaire supprimée."],
benefit="L'exonération liée à un effectif d'alternants d'au moins 3 % progressant de 10 %, les seuils et leurs atténuations, l'exclusion des salariés de mission et de leurs rémunérations, la prise en compte des salariés mis à disposition par les GEIQ et la réduction territoriale des taux à 52 % restent applicables aux années anciennes. Pour les années nouvelles, toutes les entreprises sont libérées de la CSA sans remplacement : ces allègements de CSA deviennent sans objet sans désavantage. En revanche la taxe d'apprentissage subsiste : la créance imputable sur son solde est donc conservée avec son seuil de dépassement de 5 %, ses catégories d'alternants et CIFRE, sa limite de deux points, son multiplicateur légal et ses autres modalités de L. 6241-2. Le suivi d'un an après apprentissage ou professionnalisation est maintenu dans le contrat unique. L'aide de France Travail reste ouverte pour les futurs recrutements concernés. Aucune exonération ni déduction autonome de la taxe d'apprentissage n'est supprimée.")

add('L6324-9', '''
<p>I.-Les périodes de reconversion externe mentionnées au II de l'article L. 6324-3 sont mises en œuvre dans le cadre des accords mentionnés à l'article L. 1237-17, sous les réserves suivantes.</p>
<p>A.-Dans les entreprises de cinquante à moins de trois cents salariés pourvues d'un délégué syndical, l'employeur engage une négociation collective lorsqu'au moins 10 % de l'effectif a vocation à bénéficier d'une reconversion externe sur les douze mois courant à compter de l'ouverture de la négociation. Il fournit les informations nécessaires et permet un examen effectif des propositions et contre-propositions. Si cette négociation, conduite loyalement et sérieusement, se termine sans accord, un procès-verbal de désaccord est établi selon l'article L. 2242-5. L'employeur peut alors définir unilatéralement les modalités de la période de reconversion externe, sans attendre l'expiration d'un délai minimal de trois mois. La seule ouverture de la négociation ou le silence d'un négociateur ne suffisent pas à constater son échec.</p>
<p>B.-Dans les entreprises d'au moins trois cents salariés, ainsi que dans les entreprises et groupes de dimension communautaire au sens des articles L. 2341-1 et L. 2341-2 comportant au moins un établissement ou une entreprise d'au moins cent cinquante salariés en France, l'employeur engage une négociation sur les modalités d'organisation des périodes de reconversion externe.</p>
<p>C.-Dans les entreprises de moins de cinquante salariés et celles de cinquante à moins de trois cents salariés dépourvues de délégué syndical, l'employeur peut fixer unilatéralement la période de reconversion externe. Il consulte le comité social et économique lorsqu'il en existe un.</p>
<p>II.-Les accords mentionnés au I ou, à défaut dans les cas où elle est permise, la décision unilatérale de l'employeur portent notamment sur :</p>
<p>1° La prise en charge de l'éventuel écart de rémunération du salarié dont le contrat est suspendu pendant la reconversion professionnelle externe ;</p>
<p>2° Les conditions permettant d'augmenter la durée de la période de reconversion et des actions de formation mentionnée à l'article L. 6324-4 ;</p>
<p>3° Le montant des indemnités de rupture versées au salarié bénéficiant d'une période de reconversion professionnelle, qui ne peut être inférieur aux indemnités légales dues selon le régime de rupture applicable ;</p>
<p>4° Les conditions de prise en charge totale ou partielle des frais pédagogiques des actions mentionnées à l'article L. 6324-2 par mobilisation du compte personnel de formation du salarié, avec son accord.</p>
<p>Pour les nouvelles embauches soumises à la loi instituant le contrat unique, les durées de reconversion ou de formation ne fixent aucun terme à l'emploi. Leur expiration ne vaut ni démission, ni consentement à une rupture, ni autorisation de rupture collective. Le préavis individuel de quinze jours calendaires et le barème ordinaire du contrat unique ne remplacent pas les procédures collectives, les protections spéciales et les indemnités propres au mode de rupture retenu.</p>
<p>La suppression de l'attente minimale de trois mois s'applique aux négociations ouvertes après l'entrée en vigueur de la présente réforme ; les négociations déjà ouvertes, les accords conclus et les décisions déjà prises conservent leur régime. Les actions engagées dont l'avenant précisant la durée de reconversion ou de promotion par l'alternance a été conclu avant le 1er janvier 2026 restent régies par les dispositions qui leur étaient applicables.</p>
''',
"Réduction de fond : suppression du délai plancher de trois mois avant la décision unilatérale suivant une véritable négociation infructueuse. La négociation obligatoire, le constat de désaccord, le rôle du CSE, les seuils et le consentement à l'usage du CPF restent effectifs. Réécriture intégrale des I A à C et II 1° à 4°. Coordination avec le contrat unique et maintien des planchers indemnitaires propres aux ruptures collectives ou spéciales.",
"L. 6324-3 a été lu dans ses deux versions : le nouveau contrat d'accueil est à durée indéterminée, sans essai obligatoire. Les seuils de 50, 300 et 150 salariés, les 10 % et les douze mois sont inchangés. Aucun silence ne vaut accord ; aucune décision unilatérale n'est rendue possible dans le B par assimilation au A. Coordonner L. 1237-17 et les régimes de rupture correspondants sans confondre leur indemnisation spécifique avec une démission ordinaire. La source porte valid_from au 26 octobre 2025 mais sa note fixe l'entrée en vigueur au 1er janvier 2026 : cette discordance documentaire est signalée et la transition des avenants antérieurs est expressément conservée. Les autres majorités et transmissions de L. 2232 ne sont pas recréées.",
removed=["Délai minimal de trois mois imposé aux entreprises du I A après l'ouverture de la négociation, même lorsque celle-ci s'est réellement et loyalement achevée sans accord."])

add('L6325-1-1', '''
<p>Bénéficient du contrat de professionnalisation selon les modalités des articles L. 6325-11, L. 6325-14, L. 6332-14 et L. 6332-15 : les personnes mentionnées au 1° de l'article L. 6325-1 qui n'ont pas validé un second cycle de l'enseignement secondaire et ne sont pas titulaires d'un diplôme de l'enseignement technologique ou professionnel ; les personnes mentionnées aux 1° et 2° du même article inscrites depuis plus d'un an sur la liste des demandeurs d'emploi définie à l'article L. 5411-1 ; ainsi que les personnes mentionnées au 3° de l'article L. 6325-1.</p>
<p>Ces modalités favorables restent applicables aux personnes éligibles recrutées sous contrat unique à durée indéterminée à compter de l'entrée en vigueur de la loi instituant ce contrat. Les adaptations de durée concernent l'action de professionnalisation et ne fixent pas de terme à l'emploi. Les droits attachés aux contrats antérieurs sont conservés.</p>
''',
"Les trois catégories de bénéficiaires et leurs conditions cumulatives ou alternatives sont rendues plus lisibles, sans suppression d'avantage. Coordination de fond : les modalités renforcées de durée, de formation et de financement restent ouvertes dans les nouvelles situations éligibles sous contrat unique. Le critère d'inscription depuis plus d'un an identifie ici un public bénéficiant d'un régime renforcé ; sa suppression pure aurait pu supprimer ce régime, sans alléger une déclaration.",
"L. 6325-1, L. 6325-11, L. 6325-14 et L. 6332-14 ont été lus. La négation est cumulative dans la première catégorie : absence de validation du second cycle et absence de diplôme technologique ou professionnel. L'inscription depuis plus d'un an concerne les publics des 1° et 2° ; le 3° est une voie distincte. L. 6332-15 n'a pas de fiche dans le corpus fourni : renvoi source conservé et concordance à contrôler, sans lui inventer de contenu ni fermer les prises en charge de L. 6332-14.")

add('L6325-3', '''
<p>L'employeur assure au salarié une formation lui permettant d'acquérir une qualification professionnelle ou un ou plusieurs blocs de compétences d'une certification professionnelle mentionnés au dernier alinéa de l'article L. 6113-1. Pendant l'action de professionnalisation, il lui fournit un emploi en relation avec cet objectif. Pour les contrats à durée déterminée conclus avant l'entrée en vigueur de la loi instituant le contrat unique, cette obligation s'applique pendant toute la durée du contrat, conformément au régime antérieur.</p>
<p>Le salarié travaille pour le compte de l'employeur et suit la formation prévue au contrat.</p>
<p>Les contrats de professionnalisation conclus à compter de cette entrée en vigueur sont des contrats uniques à durée indéterminée. La fin de l'action de professionnalisation ne met pas fin à l'emploi et ne permet ni d'imposer un nouvel essai, ni de remettre à zéro l'ancienneté. Les salaires, congés, créances et droits acquis sous les contrats antérieurs restent dus.</p>
''',
"Réécriture des engagements réciproques, en conservant la qualification, les blocs de compétences et le lien entre emploi et formation. Réforme de fond : suppression pour les nouveaux recrutements de l'emploi à terme adossé à la durée de professionnalisation. L'obligation pédagogique demeure ; la fin de l'action ne devient pas un motif automatique de rupture.",
"L. 6325-5 et L. 6325-11 ont été lus : la professionnalisation des nouveaux contrats uniques reste une phase limitée et l'emploi continue. Coordonner L. 6325-13 pour que ses pourcentages portent sur cette phase, non sur un emploi indéfini. La rédaction source de juin 2026, incluant les blocs de compétences, est conservée. La formation et l'obligation salariale ne sont pas des contraintes administratives redondantes à supprimer.",
removed=["Possibilité d'associer, pour les nouvelles embauches, la durée de l'emploi à celle d'un contrat de professionnalisation à durée déterminée."])

add('L6325-6-2', '''
<p>L'organisme ou le service chargé de la formation délivre une carte portant la mention « Étudiant des métiers » aux personnes mentionnées au 1° de l'article L. 6325-1 dont le contrat de professionnalisation a pour objet l'acquisition d'une qualification enregistrée au répertoire national des certifications professionnelles mentionné à l'article L. 6113-1. La délivrance n'est pas subordonnée à une durée minimale de douze mois de l'action de professionnalisation. Cette carte permet à son titulaire de faire valoir la spécificité de son statut auprès des tiers sur l'ensemble du territoire national, notamment pour accéder à des réductions tarifaires identiques à celles accordées aux étudiants de l'enseignement supérieur.</p>
<p>La carte est établie selon un modèle déterminé par voie réglementaire.</p>
<p>La suppression de la condition de durée s'applique à compter de l'entrée en vigueur de la présente réforme aux actions en cours et aux actions futures, y compris dans un contrat unique à durée indéterminée, sans nouvelle condition de durée d'emploi. Les cartes déjà délivrées restent valables selon leurs conditions de validité.</p>
''',
"Réduction de fond favorable : retrait de la condition de douze mois qui ferme l'accès à la carte et aux réductions étudiantes aux formations plus courtes. Le public du 1° de L. 6325-1 et l'objectif RNCP restent les conditions pertinentes ; aucun droit existant n'est supprimé. La reconnaissance nationale et le modèle de carte sont conservés.",
"Coordonner le modèle et les dispositions réglementaires de délivrance pour retirer la seule durée minimale de douze mois, sans exiger une attestation remplaçant cette condition. Les autres durées pédagogiques de L. 6325-11 demeurent. La carte atteste le statut de formation : elle ne garantit pas le tarif d'un prestataire au-delà du régime source et ne fixe pas la fin de l'emploi. Aucun remboursement rétroactif de réductions tarifaires non utilisées n'est créé.",
removed=["Condition d'une action de professionnalisation d'au moins douze mois pour obtenir la carte Étudiant des métiers et accéder aux avantages attachés à cette carte."])

add('L6325-12', '''
<p>La durée minimale de l'action de professionnalisation peut être portée jusqu'à vingt-quatre mois pour des personnes autres que celles mentionnées à l'article L. 6325-11 ou lorsque la nature des qualifications préparées le nécessite.</p>
<p>Une convention ou un accord collectif de branche définit ces bénéficiaires et ces qualifications. À défaut, ils sont définis par un accord collectif entre les organisations représentatives d'employeurs et de salariés signataires de l'accord constitutif d'un organisme collecteur paritaire interprofessionnel agréé.</p>
<p>Un accord national interprofessionnel peut également définir la nature de ces qualifications.</p>
<p>Pour les contrats uniques à durée indéterminée conclus à compter de l'entrée en vigueur de la loi instituant ce contrat, cette durée est celle de l'action de formation et non celle de l'emploi. Elle ne fait pas obstacle aux allongements plus favorables applicables à d'autres bénéficiaires, notamment ceux de l'article L. 6325-11. Les actions et contrats antérieurs conservent leurs durées et leurs droits.</p>
''',
"Droit constant pour la faculté d'allonger l'action à vingt-quatre mois, ses deux motifs et les trois niveaux de définition collective. Coordination de fond : cet allongement favorable porte uniquement sur la formation dans le contrat unique. La garantie de durée de formation et son accès au financement ne sont pas supprimés comme s'il s'agissait d'une attente administrative.",
"Ne pas ramener à vingt-quatre mois la possibilité de trente-six mois prévue par L. 6325-11 pour L. 6325-1-1. Le renvoi source à l'organisme collecteur paritaire interprofessionnel agréé est antérieur à la terminologie OPCO utilisée dans L. 6325-14-1 et L. 6332-14 : incohérence de vocabulaire signalée, sans substituer silencieusement des signataires différents. Coordonner le cadre interprofessionnel sur sources complètes hors lot ; l'agrément de cet organisme n'est pas un agrément individuel de chaque salarié.")

add('L6325-14-1', '''
<p>Un accord de branche ou un accord collectif entre les organisations syndicales de salariés et d'employeurs signataires de l'accord constitutif d'un opérateur de compétences interprofessionnel peut organiser la continuation et le financement, pendant six mois au plus, des actions d'évaluation et d'accompagnement et des enseignements mentionnés à l'article L. 6325-13. Ces dispositions bénéficient aux personnes dont le contrat de professionnalisation a été rompu sans qu'elles soient à l'initiative de la rupture, quelle que soit la durée initialement prévue pour l'action de professionnalisation.</p>
<p>À compter de l'entrée en vigueur de la présente réforme, la condition d'une action initiale d'au moins douze mois ne peut être opposée aux continuations nouvelles ou en cours. Cette faculté reste ouverte aux personnes éligibles dont la professionnalisation était organisée dans un contrat unique à durée indéterminée. Les financements déjà accordés et les droits acquis sont conservés ; la durée de continuation de la formation ne fixe pas de durée à un emploi.</p>
''',
"Réduction de fond favorable : suppression du seuil de douze mois de l'action initiale pour l'accès aux mécanismes conventionnels de poursuite après rupture non voulue. L'accord collectif conserve la définition et le financement du mécanisme et la limite de six mois ; aucun financement automatique nouveau ou chiffré n'est inventé.",
"Le refus d'une rupture à l'initiative du bénéficiaire reste la condition source ; aucune condition de faute ou de justification supplémentaire n'est ajoutée. Coordonner L. 6325-13 et L. 6332-14 II sur la formation après rupture dans le contrat unique. Les six mois sont un maximum de continuation pédagogique, distinct des six mois de plafond de l'indemnité ordinaire. Les accords déjà plus favorables ou les prises en charge autonomes ne sont pas réduits par cet article.",
removed=["Condition d'une action de professionnalisation initialement prévue pour au moins douze mois pour bénéficier d'une continuation conventionnelle financée après rupture non voulue."])

add('L6325-25', '''
<p>I.-Une partie de l'action de professionnalisation peut être effectuée à l'étranger. Cette mobilité ne peut excéder un an ni la moitié de la durée totale de l'action de professionnalisation. La durée de cette action peut être portée à vingt-quatre mois, sans préjudice des allongements plus favorables applicables à certains bénéficiaires. Pour les contrats uniques à durée indéterminée, ces durées ne limitent pas celle de l'emploi.</p>
<p>Pendant la mobilité à l'étranger, l'article L. 6325-13 ne s'applique pas.</p>
<p>II.-Les conditions de la mobilité à l'étranger sont fixées par une convention entre les parties au contrat de professionnalisation, l'organisme de formation en France et la ou les structures d'accueil à l'étranger.</p>
<p>La convention organise la mobilité selon l'une des modalités suivantes :</p>
<p>1° Une mise en veille du contrat de travail.</p>
<p>Dans ce cas, la structure d'accueil à l'étranger est seule responsable des conditions d'exécution du travail fixées par la législation et les conventions applicables dans l'État d'accueil, notamment en matière de santé et de sécurité au travail, de rémunération, de durée du travail, de repos hebdomadaire et de jours fériés.</p>
<p>Le bénéficiaire relève de la sécurité sociale de l'État d'accueil pendant sa mobilité, dans ou hors de l'Union européenne, sauf s'il n'y a pas le statut de salarié ou assimilé. Dans cette dernière situation, sa couverture des risques maladie, vieillesse, maternité, accidents du travail et maladies professionnelles et invalidité relève du code de la sécurité sociale. Hors de l'Union européenne, cette couverture est assurée par l'adhésion à une assurance volontaire, sous réserve des règlements européens et des conventions internationales de sécurité sociale.</p>
<p>Par dérogation au premier alinéa du présent II, pour une mobilité en entreprise, la convention peut être conclue entre les seules parties au contrat de professionnalisation et l'organisme de formation en France s'il est établi que les engagements de l'employeur de l'État d'accueil assurent au bénéficiaire des garanties équivalentes à celles de la convention prévue à ce premier alinéa, notamment pour l'organisation de la mobilité et les conditions d'accueil. Un règlement fixe la liste de ces garanties ;</p>
<p>2° Une mise à disposition du bénéficiaire auprès de la structure d'accueil à l'étranger.</p>
<p>III.-Par dérogation au premier alinéa du II, lorsque la mobilité a lieu dans un organisme de formation d'accueil situé dans ou hors de l'Union européenne, la convention peut être conclue entre le bénéficiaire, l'employeur en France et l'organisme de formation français si l'organisme de formation français ou toute structure chargée de tout ou partie des enseignements généraux, professionnels et technologiques du contrat a conclu une convention de partenariat avec cet organisme d'accueil.</p>
<p>Lorsqu'une convention de partenariat ou de mobilité déjà applicable contient des stipulations exactes et à jour régissant les mêmes conditions, celles-ci peuvent être rendues applicables à la mobilité individuelle par un renvoi écrit accepté par les parties qui doivent conclure la convention selon le II ou le III. Seules les modalités individuelles manquantes sont complétées. Il n'est exigé ni nouvelle convention autonome reproduisant ces stipulations, ni nouvelle remise des pièces déjà légalement accessibles aux signataires. Ce réemploi ne dispense ni de l'accord du bénéficiaire et des autres parties requises, ni de la détermination de la modalité de mobilité, des responsabilités, des conditions d'accueil et de la couverture sociale.</p>
<p>La simplification documentaire s'applique aux mobilités organisées à compter de l'entrée en vigueur de la présente réforme. Les conventions déjà conclues et les garanties déjà acquises demeurent valables. Pour les contrats à durée déterminée conclus avant la loi instituant le contrat unique, les limites d'un an et de la moitié de la durée totale du contrat ainsi que la faculté de porter ce contrat à vingt-quatre mois restent régies par les règles antérieures, sans autoriser un nouveau contrat à terme ou son renouvellement à terme après cette loi.</p>
''',
"Réduction de fond : suppression de la convention autonome répétant des stipulations de partenariat déjà applicables et des remises documentaires en double, avec adhésion écrite aux conditions effectivement applicables. Les deux dérogations de signature simplifiée sont conservées. Coordination du contrat unique : le plafond de moitié et l'allongement à vingt-quatre mois portent sur l'action de professionnalisation, jamais sur un emploi à durée indéterminée. Les garanties de travail, de sécurité sociale et de consentement demeurent intégrales.",
"L. 6325-11, L. 6325-13 et L. 6332-14 ont été lus. Conserver un an, la moitié de la durée pédagogique et vingt-quatre mois ; ne pas écraser les prolongations de trente-six mois pour les bénéficiaires de L. 6325-1-1. Les 1° et 2° du II et le III restent distincts ; les renvois à son premier alinéa visent toujours la convention multipartite. La mise en veille et la mise à disposition n'ont pas le même régime. Les garanties d'assurance volontaire, la réserve des règlements européens et des conventions internationales et l'exception au statut salarié de l'État d'accueil sont maintenues. Coordonner les règlements de mobilité et leurs formulaires sans supprimer de garanties de fond. Aucune inférence ne remplace le texte d'un règlement européen non fourni et aucun effet d'exonération sociale internationale nouveau n'est affirmé.",
removed=["Obligation de conclure une convention autonome répétant intégralement des conditions de mobilité ou de partenariat déjà applicables et acceptées par les signataires requis.", "Remise en double aux signataires de pièces de mobilité déjà légalement accessibles, exactes et à jour, lorsque leur réemploi suffit à établir les conditions applicables."],
benefit="Sont maintenues pour les mobilités futures : la possibilité d'exécuter une partie de la professionnalisation à l'étranger, son allongement à vingt-quatre mois sans éviction des prolongations plus favorables, la non-application de L. 6325-13 pendant la mobilité et le choix entre mise en veille et mise à disposition. La convention sans signature de l'entreprise étrangère reste possible en présence de garanties équivalentes ; celle avec les seuls trois signataires français et bénéficiaire reste possible pour un organisme de formation partenaire, dans ou hors UE. La couverture subsidiaire des risques sociaux reste intégrale dans son champ et les financements de mobilité de L. 6332-14 ne sont pas supprimés. Le renvoi à une convention existante est facultatif et ne retire aucune garantie ou qualité de signataire requise. Les anciens contrats et conventions sont protégés.")

add('L6341-1', '''
<p>L'État, les régions, les employeurs et les opérateurs de compétences participent au financement de la rémunération des stagiaires de la formation professionnelle.</p>
<p>L'opérateur France Travail mentionné à l'article L. 5312-1 y participe également, le cas échéant pour le compte de l'organisme mentionné à l'article L. 5427-1, notamment dans les conditions de l'article L. 1233-68.</p>
''',
"Réécriture à droit constant : les financeurs et la possibilité d'intervention pour le compte de l'organisme d'assurance chômage sont explicités. Aucun prélèvement, agrément ou justificatif autonome n'est créé par cet article. Retirer un financeur ou le statut rémunéré aurait supprimé un avantage sans retirer une formalité redondante.",
"L. 5312-1 identifie France Travail ; L. 5427-1 et L. 1233-68 ont été lus. Le premier porte un état d'abrogation différée dans le corpus : son éventuel successeur devra être coordonné selon les dispositions temporelles applicables, sans supprimer le financement. L. 1233-68 vise un contrat de sécurisation professionnelle et non un contrat d'emploi : sa durée n'est pas convertie en CDI. Ses références aux activités en CDD et en intérim doivent être coordonnées séparément au contrat unique. La présente rédaction n'attribue pas une rémunération salariale à toute période de formation et ne modifie ni montants ni conditions propres des prises en charge.")

add('L7313-5', '''
<p>Le contrat de travail du voyageur, représentant ou placier peut prévoir une période d'essai d'au plus trois mois.</p>
<p>Pour les contrats uniques à durée indéterminée conclus à compter de l'entrée en vigueur de la loi instituant ce contrat, l'essai doit être expressément stipulé et ne peut être renouvelé. Sa rupture est soumise au préavis individuel de quinze jours calendaires de l'une ou l'autre partie. Ce préavis ne prolonge pas l'essai ; la part du préavis patronal qui ne peut être exécutée avant son échéance est indemnisée selon les règles du contrat unique. Un changement de clientèle, d'affectation ou de mission au cours du même contrat n'ouvre pas un nouvel essai.</p>
<p>Les périodes d'essai stipulées dans les contrats conclus auparavant conservent leur régime antérieur et leur limite de trois mois, sans remise à zéro d'une période déjà accomplie.</p>
''',
"Droit constant pour le caractère facultatif et la limite de trois mois de l'essai des VRP. Coordination de fond : interdiction de renouvellement pour le nouveau contrat unique et articulation explicite avec quinze jours de préavis sans prolongation de l'essai. La fin d'une affectation n'autorise pas un essai nouveau.",
"Coordonner L. 1221-19, L. 1221-21 à L. 1221-23, L. 1221-25 et L. 1221-26 selon travail dans coordination.json. Les trois mois sont un maximum, non un essai automatique ; une stipulation plus courte reste possible. La compensation du reliquat patronal ne doit pas être confondue avec l'indemnité ordinaire conditionnée à un an. L'ancien régime spécial de trois mois n'est pas porté à huit mois.")

add('L7313-10', '''
<p>Lorsque la rupture du contrat de travail d'un voyageur, représentant ou placier employé hors de France entraîne son retour en France, la durée normale du voyage de retour s'ajoute à celle du préavis pour les contrats conclus avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée.</p>
<p>Pour les contrats uniques conclus à compter de cette entrée en vigueur, le préavis individuel reste fixé à quinze jours calendaires, que la rupture soit à l'initiative de l'employeur ou du salarié. Le voyage de retour ne prolonge pas ce préavis et le salarié n'est pas tenu de rester au service de l'employeur au-delà de ces quinze jours pour ce seul motif.</p>
<p>Pour ces nouveaux contrats, lorsque la rupture de l'emploi exercé hors de France entraîne le retour du salarié en France, quelle que soit la partie qui en prend l'initiative, le salarié conserve, en sus des sommes dues au titre du préavis, une indemnisation égale à la rémunération qu'il aurait perçue pendant la durée normale du voyage de retour. Le temps de voyage effectué pendant le préavis est pris sur ce préavis, sans perte de la rémunération correspondante. Cette garantie spéciale de retour, à la charge de l'employeur, est distincte de l'indemnité ordinaire de rupture et ne dépend ni de son seuil d'un an ni de son plafond de six mois. Elle ne crée pas d'indemnité ordinaire de démission. Les dispenses de préavis plus favorables au salarié et les droits acquis au titre des contrats antérieurs sont conservés.</p>
''',
"Réduction de fond : retrait de l'allongement automatique du préavis des nouveaux contrats, notamment de l'obligation pesant sur un salarié qui démissionne de rester au-delà de quinze jours pour le voyage. Le bénéfice salarial de la durée supplémentaire est conservé sous forme d'une garantie distincte, quelle que soit l'initiative de la rupture, sans allonger l'emploi. Le régime antérieur demeure pour le stock de contrats.",
"L. 7313-9 a été lu et propose quinze jours calendaires pour les nouveaux contrats avec maintien des anciens minima d'un, deux et trois mois. Le présent article ne les rétablit pas pour les nouvelles embauches. La rémunération correspondant à la durée normale du retour conserve la composante favorable de l'ancien allongement, que la rupture soit patronale ou salariale ; il ne s'agit ni d'un nouveau forfait de frais de voyage ni d'un taux d'indemnité ordinaire. Cette conversion explicite maintient le bénéfice sans rétablir une obligation de travail au-delà des quinze jours. Les garanties conventionnelles ou contractuelles de transport et de rapatriement gardent leur champ. Les autorisations de licenciement et procédures collectives restent distinctes du préavis individuel.",
removed=["Allongement automatique du préavis individuel des nouveaux VRP à raison du voyage de retour, avec obligation de maintien au service au-delà de quinze jours en cas de départ du salarié."])

add('L7313-14', '''
<p>Le présent article est abrogé pour les contrats conclus à compter de l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée. Il n'autorise plus la conclusion ou le renouvellement d'un contrat de travail à durée déterminée de voyageur, représentant ou placier.</p>
<p>Pour les contrats à durée déterminée conclus avant cette entrée en vigueur, l'indemnité de clientèle reste due, en l'absence de faute grave, lorsque l'employeur rompt le contrat avant le terme convenu ou lorsque le contrat arrivé à son terme n'est pas renouvelé. Cette garantie, les créances et les recours restent applicables même si le terme, la rupture, le paiement ou l'action en justice sont postérieurs à l'entrée en vigueur de la loi. Elle ne permet pas un nouveau renouvellement à durée déterminée après cette date.</p>
<p>Pour les nouveaux contrats uniques à durée indéterminée, le droit à l'indemnité de clientèle relève de l'article L. 7313-13. La présente abrogation ne supprime ni cette indemnité spéciale ni les droits valablement acquis au titre d'un contrat antérieur.</p>
''',
"Abrogation prospective du dispositif exclusivement attaché aux CDD de VRP, en coordination avec l'interdiction de nouveaux CDD. L'abrogation ne porte pas sur l'indemnité de clientèle : ses deux cas d'ouverture pour les anciens CDD sont intégralement maintenus et son fondement CDI reste L. 7313-13 pour les recrutements futurs.",
"L. 7313-13 a été lu : conserver l'absence de faute grave, la clientèle apportée, créée ou développée, les rémunérations spéciales de même objet, les diminutions imputables au salarié et le cas d'incapacité permanente totale par accident ou maladie. Ces conditions autonomes ne sont pas remplacées par le barème ordinaire de 0,20 mois. L'échéance d'un ancien CDD ouvre encore la garantie en cas de non-renouvellement, y compris lorsque le renouvellement futur est désormais interdit. Coordonner L. 7313-15 sans amputer les dommages de rupture anticipée des anciens contrats.",
repeal="Fondement spécial relatif aux contrats à durée déterminée de VRP pour les recrutements futurs, avec conservation intégrale des indemnités de clientèle dues au titre des CDD antérieurs et maintien du régime CDI autonome.")

add('L7313-15', '''
<p>L'indemnité de clientèle est distincte de l'indemnité réparant la rupture abusive d'un contrat de travail à durée indéterminée. Elle est également distincte de l'indemnité due pour la rupture anticipée d'un contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée.</p>
<p>Pour les nouveaux contrats uniques, l'indemnité de clientèle conserve son objet propre selon l'article L. 7313-13. Ni le préavis individuel de quinze jours calendaires ni les conditions de l'indemnité ordinaire de rupture ne suppriment la réparation d'une rupture illégale, y compris avant un an d'ancienneté. Le présent article n'autorise aucun nouveau contrat à durée déterminée et ne réduit aucune créance ou action attachée à un contrat antérieur.</p>
''',
"Les deux distinctions indemnitaires de la source sont conservées et clarifiées. Coordination de fond : la branche CDD est réservée aux contrats antérieurs ; les nouveaux emplois relèvent du contrat unique sans absorption des dommages d'une illégalité ni de la fonction propre de l'indemnité de clientèle.",
"Lire ensemble L. 7313-13, L. 7313-14, L. 7313-16 et L. 1234-9. La distinction entre objets d'indemnités ne décide pas à elle seule de toutes les règles de cumul ou de non-cumul : aucun cumul automatique avec une indemnité de même objet n'est créé. Les dommages d'une rupture illégale restent distincts du zéro d'indemnité ordinaire avant un an et du plafond légal de six mois. Le texte ne permet pas de liquider forfaitairement à l'avance une indemnité de clientèle, interdite par L. 7313-16.")

add('L7332-1', '''
<p>Pour les contrats mentionnés au 2° de l'article L. 7331-2 conclus à compter de l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, une période d'essai peut être expressément stipulée pour trois mois au plus, sans renouvellement. Pour les contrats conclus auparavant, la durée de l'essai, renouvellement compris, reste limitée à huit mois selon les règles antérieures.</p>
<p>Lorsque les parties ont auparavant conclu un contrat d'appui au projet d'entreprise pour la création ou la reprise d'une activité économique, prévu à l'article L. 127-1 du code de commerce, ou tout autre contrat, la durée de ces contrats est déduite de la durée d'essai applicable en vertu du premier alinéa. Cette déduction ne peut laisser subsister qu'une durée positive ou nulle ; elle ne peut ouvrir un nouvel essai.</p>
<p>La rupture de l'essai d'un nouveau contrat unique relève du préavis individuel de quinze jours calendaires de l'une ou l'autre partie, sans prolongation de l'essai. L'employeur indemnise la fraction de son préavis qui ne peut être exécutée avant la fin de l'essai. La fin d'un accompagnement ou le changement d'activité au cours du même contrat ne crée pas de nouvel essai. Les périodes déjà accomplies, l'ancienneté et les créances acquises restent prises en compte.</p>
''',
"Réduction de fond : suppression de l'essai pouvant atteindre huit mois avec renouvellement pour les nouveaux entrepreneurs salariés ; maximum de trois mois sans renouvellement. La déduction favorable du CAPE ou de tout autre contrat antérieur entre les parties est intégralement conservée et s'impute sur ce nouveau maximum. Les essais des contrats anciens gardent leur régime.",
"L. 7331-2 a été lu : contrat écrit comprenant les droits sur la clientèle et la propriété intellectuelle, sans confusion avec un mandat ou une simple convention d'accompagnement. Le CAPE de L. 127-1 du code de commerce, hors des cinq codes et non fourni intégralement, reste un renvoi identifié ; son régime n'est pas présenté comme réécrit. Coordonner le règlement des coopératives et L. 1221-19, L. 1221-21 à L. 1221-23, L. 1221-25 et L. 1221-26. La déduction de toute durée préalable est maintenue sans ajouter une condition d'identité d'activité ou limiter le bénéfice au seul CAPE ; un reliquat négatif vaut absence d'essai, non une dette du salarié.",
removed=["Possibilité de prévoir, pour les nouveaux entrepreneurs salariés de coopératives d'activité et d'emploi, une période d'essai renouvelable pouvant atteindre huit mois au total."])


# L'annexe est composée par fragments : prose complète et quatre tableaux complets.
# Les cellules de résultats et de points sont conservées exactement ; toutes les
# méthodes sont rédigées ci-dessous et leurs attributs de présentation sont retirés.
import copy
import xml.etree.ElementTree as ET

annex_source = next(a for a in sources if a['number'] == 'Annexe I')
annex_root = ET.fromstring('<root>' + annex_source['source_xml'] + '</root>')
tables = [copy.deepcopy(t) for t in annex_root.findall('table')]
for table in tables:
    for element in table.iter():
        element.attrib = {k: v for k, v in element.attrib.items() if k in {'rowspan', 'colspan'}}
    for cell in list(table.iter('td')) + list(table.iter('th')):
        text = ' '.join(''.join(cell.itertext()).split())
        for child in list(cell):
            cell.remove(child)
        cell.text = text
    headings = table.findall('.//tr')[0]
    for cell in headings:
        cell.text = {'INDICATEUR': 'Indicateur', 'METHODE DE CALCUL': 'Méthode de calcul', 'RESULTATS OBTENUS': 'Résultat obtenu', 'NOMBRE DE POINTS': 'Nombre de points'}[cell.text]


def cell_xml(table_index, row_index, cell_index, xml):
    cell = tables[table_index].findall('.//tr')[row_index][cell_index]
    attrs = dict(cell.attrib)
    replacement = ET.fromstring('<td>' + xml.strip() + '</td>')
    cell.clear()
    cell.attrib.update(attrs)
    cell.text = replacement.text
    for child in replacement:
        cell.append(child)


cell_xml(0, 1, 0, "Écart de rémunération entre les femmes et les hommes, mentionné au 1° de l'article D. 1142-2.")
cell_xml(0, 1, 1, '''
<p>a) Les salariés sont répartis en groupes croisant la catégorie de postes équivalents et les quatre tranches d'âge suivantes : moins de 30 ans ; de 30 à 39 ans ; de 40 à 49 ans ; 50 ans et plus.</p>
<p>Pour les postes équivalents, l'employeur peut retenir, après consultation du comité social et économique, les niveaux ou coefficients hiérarchiques de la classification de branche ou les niveaux d'une autre méthode de cotation des postes. L'adoption de cette dernière méthode est soumise à l'avis du comité. Une seule consultation peut porter sur son adoption et sur son utilisation pour la répartition ; une méthode déjà adoptée après avis du comité et demeurée inchangée n'est pas soumise à un nouvel avis du seul fait de sa réutilisation annuelle pour cet indicateur. Les autres consultations légalement requises restent applicables.</p>
<p>Si l'employeur ne retient ni les niveaux ou coefficients hiérarchiques ni une autre cotation des postes, ou si ces méthodes ne permettent pas le calcul, il utilise les quatre catégories socioprofessionnelles suivantes : ouvriers ; employés ; techniciens et agents de maîtrise ; ingénieurs et cadres.</p>
<p>b) Seuls les groupes comprenant au moins trois hommes et trois femmes sont retenus. Si cette condition empêche le calcul par niveau ou coefficient hiérarchique au regard du paragraphe 5.1, ce classement est écarté et les salariés sont regroupés selon les quatre catégories socioprofessionnelles du a).</p>
<p>c) Dans chaque groupe retenu, la rémunération moyenne est calculée séparément pour les femmes et les hommes. La rémunération de chaque salarié est d'abord reconstituée en équivalent temps plein, puis la moyenne est établie.</p>
<p>d) L'écart de rémunération de chaque groupe est exprimé en pourcentage : la rémunération moyenne des femmes est soustraite à celle des hommes, puis la différence est rapportée à la rémunération moyenne des hommes.</p>
<p>e) Le seuil de pertinence est de 5 % pour un groupe constitué par catégorie socioprofessionnelle et de 2 % pour un groupe constitué par niveau ou coefficient hiérarchique.</p>
<p>Si l'écart est positif, ce seuil est soustrait à l'écart sans que le résultat puisse être inférieur à zéro. Si l'écart est négatif, le seuil y est ajouté sans que le résultat puisse être supérieur à zéro.</p>
<p>f) L'écart ainsi ajusté de chaque groupe est multiplié par le rapport entre l'effectif de ce groupe et l'effectif total des groupes retenus. La somme de ces résultats constitue l'écart global de rémunération entre les femmes et les hommes.</p>
<p>g) Le résultat final est la valeur absolue de cet écart global, arrondie à la première décimale.</p>
''')
cell_xml(1, 1, 0, "Écart de taux d'augmentations individuelles de salaire, hors promotions, entre les femmes et les hommes, mentionné au 2° de l'article D. 1142-2.")
cell_xml(1, 1, 1, '''
<p>a) Les salariés sont répartis dans les quatre catégories socioprofessionnelles définies au paragraphe 4.1.</p>
<p>b) Seuls les groupes comprenant au moins dix femmes et dix hommes sont retenus.</p>
<p>c) Dans chaque groupe, le taux d'augmentations est calculé séparément pour les femmes et les hommes. Il est égal à la proportion, exprimée en pourcentage, de salariés ayant reçu une augmentation individuelle (1) pendant la période de référence. Les augmentations correspondant à une promotion (2) sont exclues.</p>
<p>d) Dans chaque groupe, l'écart de taux d'augmentations, exprimé en points de pourcentage, est obtenu en soustrayant le taux des femmes à celui des hommes.</p>
<p>e) Chaque écart est multiplié par le rapport entre l'effectif du groupe et l'effectif total des groupes retenus. La somme de ces résultats donne l'écart global de taux d'augmentations entre les femmes et les hommes.</p>
<p>f) Le résultat final est la valeur absolue de cet écart global, arrondie à la première décimale.</p>
''')
cell_xml(1, 5, 0, "Écart de taux de promotions entre les femmes et les hommes, mentionné au 3° de l'article D. 1142-2.")
cell_xml(1, 5, 1, '''
<p>a) Les salariés sont répartis dans les quatre catégories socioprofessionnelles définies au paragraphe 4.1.</p>
<p>b) Seuls les groupes comprenant au moins dix hommes et dix femmes sont retenus.</p>
<p>c) Dans chaque groupe, le taux de promotions est calculé séparément pour les femmes et les hommes. Il est égal à la proportion, exprimée en pourcentage, de salariés ayant bénéficié d'une promotion (2) pendant la période de référence. Les augmentations exclues du calcul de l'indicateur d'augmentations individuelles parce qu'elles correspondent à des promotions sont prises en compte pour le présent indicateur.</p>
<p>d) Dans chaque groupe, l'écart de taux de promotions, exprimé en points de pourcentage, est obtenu en soustrayant le taux des femmes à celui des hommes.</p>
<p>e) Chaque écart est multiplié par le rapport entre l'effectif du groupe et l'effectif total des groupes retenus. La somme de ces résultats donne l'écart global de taux de promotions entre les femmes et les hommes.</p>
<p>f) Le résultat final est la valeur absolue de cet écart global, arrondie à la première décimale.</p>
''')
cell_xml(1, 9, 0, '''
<p>(1) Une augmentation individuelle est une augmentation individuelle du salaire de base du salarié concerné.</p>
<p>(2) Une promotion est le passage à un niveau ou à un coefficient hiérarchique supérieur.</p>
''')
cell_xml(2, 1, 0, "Pourcentage de salariées revenues de congé de maternité pendant l'année de référence et ayant bénéficié d'une augmentation à leur retour au cours de cette même période, lorsque des augmentations sont intervenues pendant leur congé ; indicateur mentionné au 4° de l'article D. 1142-2.")
cell_xml(3, 1, 0, "Nombre de salariés du sexe sous-représenté parmi les dix salariés ayant perçu les plus hautes rémunérations, mentionné au 5° de l'article D. 1142-2.")
cell_xml(3, 1, 1, "Parmi les dix salariés ayant perçu les plus hautes rémunérations, le nombre de femmes et celui d'hommes sont décomptés séparément. L'indicateur est le plus petit de ces deux nombres, chacun étant compris entre 0 et 10.")

intro = '''
<p>MODALITÉS DE CALCUL ET D'ÉVALUATION DES INDICATEURS DE L'ARTICLE D. 1142-2 POUR LES ENTREPRISES DE PLUS DE 250 SALARIÉS</p>
<p>1. Période de référence</p>
<p>L'employeur choisit une période de référence de douze mois consécutifs. Chaque année, au plus tard le 1er mars, il calcule les indicateurs à partir des données de la période annuelle choisie précédant l'année de publication.</p>
<p>2. Salariés à prendre en compte pour le calcul des indicateurs</p>
<p>L'effectif retenu pour les indicateurs est apprécié sur la période annuelle de référence choisie par l'employeur.</p>
<p>Ne sont pas pris en compte : les apprentis ; les titulaires d'un contrat de professionnalisation ; les salariés mis à disposition par une entreprise extérieure ; les salariés expatriés ; les salariés absents pendant plus de la moitié de la période annuelle de référence.</p>
<p>Les caractéristiques individuelles suivantes sont appréciées au dernier jour de la période annuelle de référence ou au dernier jour de présence du salarié dans l'entreprise :</p>
<p>- l'âge ;</p>
<p>- le niveau ou le coefficient hiérarchique selon la classification de branche ;</p>
<p>- le niveau selon la méthode de cotation des postes de l'entreprise ;</p>
<p>- la catégorie socioprofessionnelle.</p>
<p>Pour les contrats uniques à durée indéterminée conclus à compter de l'entrée en vigueur de la loi instituant ce contrat, les exclusions liées à l'apprentissage ou à la professionnalisation correspondent à la période d'apprentissage ou à l'action de professionnalisation. La seule poursuite de l'emploi après cette phase ne constitue pas une cause d'exclusion.</p>
<p>3. Éléments de rémunération à prendre en compte pour le calcul des indicateurs</p>
<p>La rémunération de chaque salarié, au sens de l'article L. 3221-3, est reconstituée en équivalent temps plein sur la période annuelle de référence. Sont exclus : les indemnités de licenciement et de départ à la retraite ; les primes liées à une sujétion particulière qui ne concerne pas la personne du salarié ; les primes d'ancienneté ; les heures supplémentaires ; les heures complémentaires ; les versements d'intéressement et de participation.</p>
<p>4. Méthode de calcul des indicateurs et barème applicable aux résultats</p>
<p>Les indicateurs de l'article D. 1142-2 sont calculés et évalués selon les tableaux ci-dessous, sur un barème total de 0 à 100 points.</p>
<p>4.1. Indicateur d'écart de rémunération entre les femmes et les hommes</p>
'''
middle_2 = "<p>4.2. Indicateurs d'écarts de taux d'augmentations individuelles et de promotions entre les femmes et les hommes</p>"
middle_3 = "<p>4.3. Indicateur du pourcentage de salariées ayant bénéficié d'une augmentation dans l'année suivant leur retour de congé de maternité</p>"
middle_4 = "<p>4.4. Indicateur du nombre de salariés du sexe sous-représenté parmi les dix plus hautes rémunérations</p>"
end = '''
<p>5. Niveau de résultat</p>
<p>Le niveau de résultat de l'entreprise pour les indicateurs de l'article D. 1142-2 est égal à la somme des points obtenus pour chaque indicateur selon le barème du paragraphe 4.</p>
<p>5.1. Détermination du niveau de résultat lorsque des indicateurs ne peuvent pas être calculés</p>
<p>Un indicateur ne peut pas être calculé dans les cas suivants :</p>
<p>- pour le 1° de l'article D. 1142-2, lorsque l'effectif total retenu selon le paragraphe 4.1 représente moins de 40 % de l'effectif à retenir pour l'ensemble des indicateurs selon le paragraphe 2 ;</p>
<p>- pour le calcul des indicateurs des 2° et 3° du même article, soit lorsqu'aucune promotion ou aucune augmentation individuelle n'est intervenue pendant la période annuelle de référence, soit lorsque l'effectif total retenu selon le paragraphe 4.2 représente moins de 40 % de l'effectif à retenir pour l'ensemble des indicateurs selon le paragraphe 2 ;</p>
<p>- pour le 4° du même article, lorsqu'aucune salariée n'est revenue de congé de maternité pendant la période annuelle de référence ou qu'aucune augmentation n'est intervenue pendant ces congés.</p>
<p>Dans ces cas, si un ou plusieurs indicateurs ne peuvent pas être calculés, les autres le sont. Le total de points obtenu est ramené à cent par proportionnalité.</p>
<p>Si le nombre maximal de points pouvant être obtenu avant cette opération de proportionnalité est inférieur à soixante-quinze, le niveau de résultat du premier alinéa du paragraphe 5 ne peut pas être déterminé pour la période annuelle concernée. Cette impossibilité ne dispense pas l'entreprise de mettre les indicateurs calculables à la disposition du comité social et économique et des services du ministre chargé du travail selon l'article D. 1142-5.</p>
<p>Les mêmes calculs, résultats et explications, exacts et à jour, sont réemployés pour leur publication, leur mise à disposition du comité et leur transmission aux services du ministre. Aucun second calcul identique ni nouvelle collecte des mêmes pièces n'est exigé du seul fait de la pluralité de ces destinations. Les modalités de publicité, d'information, de transmission et de protection des données qui leur sont propres restent applicables.</p>
<p>5.2. Prise en compte des mesures de correction</p>
<p>Pour ne pas pénaliser les entreprises qui prennent des mesures adéquates et pertinentes et, le cas échéant, programment un rattrapage salarial en application de l'article L. 1142-9, les règles suivantes s'appliquent lorsque l'indicateur du 1° de l'article D. 1142-2 est calculable et que l'entreprise n'y obtient pas la note maximale :</p>
<p>- l'entreprise obtient le maximum de points pour l'indicateur du 2° si les écarts constatés pour cet indicateur favorisent la population dont la rémunération est la plus faible selon le résultat du 1° ;</p>
<p>- l'entreprise obtient le maximum de points pour l'indicateur du 3° si les écarts constatés pour cet indicateur favorisent cette même population.</p>
<p>Les simplifications de consultation et de réemploi s'appliquent aux calculs réalisés à compter de l'entrée en vigueur de la présente réforme, sans imposer de refaire un calcul ou un dépôt déjà effectué. Les résultats antérieurs, les corrections, les droits des salariés et les recours conservent leur régime. La présente rédaction ne proroge pas l'application de l'annexe au-delà de son abrogation différée prévue par les textes en vigueur.</p>
'''
fragments = [intro, ET.tostring(tables[0], encoding='unicode'), middle_2,
             ET.tostring(tables[1], encoding='unicode'), middle_3,
             ET.tostring(tables[2], encoding='unicode'), middle_4,
             ET.tostring(tables[3], encoding='unicode'), end]
for index, fragment in enumerate(fragments):
    Path(f'fragments/annexe_proposition_{index+1:02}.xml').write_text(fragment.strip())

add('Annexe I', '\n'.join(fragment.strip() for fragment in fragments),
"Réécriture intégrale des périodes, effectifs, rémunérations, méthodes, barèmes et règles de résultat. Les quatre tableaux et chacune de leurs lignes de points sont conservés. Réduction de fond ciblée : une consultation commune du CSE peut couvrir l'adoption et l'utilisation d'une cotation ; une cotation déjà adoptée après avis et inchangée n'appelle pas un nouvel avis annuel pour le seul calcul. Réemploi des mêmes données plutôt que calculs et collectes en double. Les indicateurs, majorations favorables de note pour rattrapage, exceptions d'incalculabilité et protections d'égalité salariale sont maintenus. La phase pédagogique du contrat unique ne devient pas une exclusion permanente de l'emploi poursuivi.",
"D. 1142-2, D. 1142-5 et L. 1142-8 à L. 1142-10 ont été lus. Les quatre tableaux complets ont été comparés cellule par cellule pour les résultats, notes et fusions ; aucun barème n'est supprimé. Vérifiés : 250 salariés, douze mois, 1er mars, quatre âges, groupes de 3 ou 10 personnes de chaque sexe, seuils de 5 % et 2 %, arrondi à la première décimale, poids de 40/20/15/15/10 points, incalculabilité à moins de 40 %, seuil de 75 points avant proportionnalité, et maximum des indicateurs 2°/3° en cas de correction favorable. La source du tableau 4.2 renvoie dans sa méthode de promotions à l'indicateur « défini au (1) », alors que (1) définit l'augmentation individuelle : ambiguïté signalée et objet exprimé explicitement sans changer l'exclusion des promotions du 2°. Le « passage à niveau » de la note (2) est reformulé en passage à un niveau. Le 5.1 conserve l'alternative source « aucune promotion ou aucune augmentation individuelle » pour les 2° et 3°, sans la remplacer silencieusement par une condition cumulative. Ne pas confondre cet index avec les règles relatives aux instances dirigeantes. La source est ABROGE_DIFF avec valid_until au 1er mars 2029 : aucune prorogation ni réouverture n'est proposée. Coordonner les textes successeurs et les exigences européennes de transparence salariale sur leurs sources complètes ; aucun droit européen n'est réputé supprimé. D. 1142-5 doit reprendre le réemploi sans retirer l'information du CSE ou le circuit ministériel maintenu par la loi.",
removed=["Consultations distinctes du CSE pour l'adoption et l'usage de la même méthode de cotation, et nouvel avis annuel sur une méthode déjà adoptée après avis et demeurée inchangée.", "Second calcul identique et nouvelle collecte des mêmes données ou pièces pour la seule répétition des résultats de l'index auprès de ses destinataires légaux."],
benefit="L'annexe comporte des allègements méthodologiques et garanties favorables conservés : exclusions des apprentis, professionnalisants, salariés extérieurs, expatriés et absents plus de la moitié de la période ; éléments de rémunération exclus ; faculté de classement par branche ou cotation ; seuils de pertinence de 5 % et 2 % avec arrêt à zéro ; groupes insuffisants et règles d'incalculabilité, proportionnalité et impossibilité de score sous 75 points disponibles ; notes maximales pour augmentations ou promotions corrigeant un désavantage salarial. Toutes les notes et conditions de ces avantages demeurent pour les calculs futurs durant l'application de l'annexe. L'information du CSE, la transparence des résultats, les augmentations de retour de maternité et les droits d'égalité salariale ne sont pas supprimés. Aucun prélèvement fiscal n'est institué ou relevé ; les pénalités législatives autonomes ne sont ni élargies ni réécrites par cette annexe.")

assert len(answers) == len(sources) == 22
assert [a['source_id'] for a in answers] == [a['source_id'] for a in sources]
Path('answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
